import backdrops from '@config/video-backdrops.json';

const byVideo: Record<string, string> = backdrops;

/**
 * CSS `url(...)` of a video's tiny blurred first frame, or undefined if none was generated.
 * It is only ever a background BEHIND the video: while the video loads, visitors see a soft
 * preview of it instead of a black box, and the video paints over it. Never an image in front.
 * Generated by `npm run video:backdrops`.
 */
export const videoBackdrop = (src: string | undefined): string | undefined => {
  const dataUri = src ? byVideo[src] : undefined;
  return dataUri ? `url(${dataUri})` : undefined;
};
